define([],function(){function getRemainingChars(textarea,config,Utils){var maxLength=parseInt(textarea.getAttribute('maxlength'),10);if(!isFinite(maxLength)||maxLength<=0){maxLength=Utils.safeInt(config.notemaxlength,2000)}return Math.max(0,maxLength-textarea.value.length)}function updateCharCounter(textarea,config,Utils){if(!textarea){return 0}var remaining=getRemainingChars(textarea,config,Utils);var panel=textarea.closest('.videotrack-notes-panel');var hint=panel?panel.querySelector('.videotrack-note-charcount'):null;if(hint){hint.textContent=remaining+' '+config.charsremaininglabel}return remaining}function setButtonState(saveBtn,playing){if(!saveBtn){return}saveBtn.disabled=!playing;saveBtn.setAttribute('aria-disabled',playing?'false':'true');saveBtn.classList.toggle('videotrack-note-save-disabled',!playing)}function appendRow(noteid,videotime,text,config,Utils){var list=document.getElementById('videotrack-notes-list');if(!list){return}var li=document.createElement('li');li.className='videotrack-note-item';li.dataset.noteid=noteid;var timeSpan=document.createElement('span');timeSpan.className='videotrack-note-time text-muted me-1 small';timeSpan.textContent=Utils.formatSeconds(videotime);li.appendChild(timeSpan);var textSpan=document.createElement('span');textSpan.className='videotrack-note-text';textSpan.textContent=text;li.appendChild(textSpan);var delBtn=document.createElement('button');delBtn.type='button';delBtn.className='btn btn-link btn-sm videotrack-delete-note ms-1';delBtn.dataset.noteid=noteid;delBtn.textContent=config.removenotelabel;delBtn.setAttribute('aria-label',(config.removenotelabel||'')+' — '+Utils.formatSeconds(videotime));li.appendChild(delBtn);list.appendChild(li);var maxRenderedNotes=Utils.safeInt(config.notesmaxrendered,200);var removed=0;while(list.children.length>maxRenderedNotes){list.removeChild(list.firstElementChild);removed++}if(removed>0&&config.notesrenderlimitlabel&&typeof config.showStatusMessage==='function'){config.showStatusMessage(config.notesrenderlimitlabel,false,config.dismisslabel)}}function installHandler(deps){var Ajax=deps.Ajax;var Log=deps.Log;var Utils=deps.Utils;var config=deps.config;var state=deps.state;var getCurrentVideoTime=deps.getCurrentVideoTime;var saveCurrentProgress=deps.saveCurrentProgress;var showStatusMessage=deps.showStatusMessage;config.showStatusMessage=showStatusMessage;var showErrorStatusMessage=deps.showErrorStatusMessage||function(error,fallbackMessage,dismissLabel){var message=(error&&error.message)?error.message:fallbackMessage;showStatusMessage(message,true,dismissLabel)};if(!config.studentnotesenabled){return}var saveBtn=document.getElementById('videotrack-note-save');var textarea=document.getElementById('videotrack-note-input');var savingNote=false;var charCounterTimer=null;if(!saveBtn||!textarea){return}function ajax(methodname,args){return Ajax.call([{methodname:methodname,args:args}])[0]}function setLocalButtonState(playing){setButtonState(saveBtn,playing)}var playStateHandler=function(e){setLocalButtonState(e.detail&&e.detail.playing)};document.addEventListener('videotrack:playstate',playStateHandler);window.addEventListener('beforeunload',function(){document.removeEventListener('videotrack:playstate',playStateHandler);if(charCounterTimer){window.clearTimeout(charCounterTimer);charCounterTimer=null}},{once:true});saveBtn.addEventListener('click',function(){if(savingNote||saveBtn.getAttribute('aria-disabled')==='true'){if(!state.playing){showStatusMessage(config.noteplaybackrequiredlabel||config.reactionunavailablelabel,false,config.dismisslabel)}return}var maxLength=Utils.safeInt(config.notemaxlength,2000);var text=textarea.value.trim();if(maxLength>0&&text.length>maxLength){text=text.substring(0,maxLength);textarea.value=text;updateCharCounter(textarea,config,Utils);if(config.notetruncatedlabel){showStatusMessage(config.notetruncatedlabel,false,config.dismisslabel)}}if(!text){textarea.focus();return}var currentTime=getCurrentVideoTime();savingNote=true;saveBtn.setAttribute('aria-disabled','true');saveBtn.setAttribute('aria-busy','true');saveBtn.classList.add('videotrack-note-save-saving');saveCurrentProgress('note').then(function(){return ajax('mod_videotrack_save_note',{cmid:config.cmid,sessionid:state.sessionid,videotime:currentTime,notetext:text,playbackrate:state.playbackrate||1})}).then(function(response){savingNote=false;saveBtn.removeAttribute('aria-busy');saveBtn.classList.remove('videotrack-note-save-saving');setLocalButtonState(state.playing);if(response&&response.noteeventid){appendRow(response.noteeventid,currentTime,text,config,Utils);textarea.value='';updateCharCounter(textarea,config,Utils);textarea.focus();if(config.notesavedlabel){showStatusMessage(config.notesavedlabel,false,config.dismisslabel)}}}).catch(function(error){savingNote=false;saveBtn.removeAttribute('aria-busy');saveBtn.classList.remove('videotrack-note-save-saving');setLocalButtonState(state.playing);showErrorStatusMessage(error,config.noteerrorlabel,config.dismisslabel)})});var noteList=document.getElementById('videotrack-my-notes');if(noteList){noteList.addEventListener('click',function(e){var delBtn=e.target.closest('.videotrack-delete-note');if(!delBtn||!noteList.contains(delBtn)){return}var noteid=Utils.safeInt(delBtn.dataset.noteid,0);if(!noteid){return}ajax('mod_videotrack_delete_note',{cmid:config.cmid,reactioneventid:noteid}).then(function(response){if(response&&response.deleted){var li=delBtn.closest('li');if(li){var list=li.parentElement;li.remove();var next=list?list.querySelector('.videotrack-note-item button'):null;if(next){next.focus()}else if(textarea){textarea.focus()}if(config.notedeletedlabel){showStatusMessage(config.notedeletedlabel,false,config.dismisslabel)}}}}).catch(function(err){Log.debug('mod_videotrack:note deletion failed-'+err);showStatusMessage(config.noteerrorlabel,true,config.dismisslabel)})})}textarea.addEventListener('input',function(){if(charCounterTimer){window.clearTimeout(charCounterTimer)}charCounterTimer=window.setTimeout(function(){updateCharCounter(textarea,config,Utils);charCounterTimer=null},120)})}function installToggle(config,Utils,contextLabel){var btn=document.getElementById('videotrack-notes-toggle');var body=document.getElementById('videotrack-notes-body');if(!btn||!body){return}var key='videotrack_notes_collapsed_'+(config.cmid?String(config.cmid):'x');var labelContext=contextLabel||'notes panel state';function setCollapsed(collapsed){body.style.display=collapsed?'none':'';btn.setAttribute('aria-expanded',collapsed?'false':'true');var label=collapsed?config.noteshowlabel:config.noteshidelabel;btn.textContent=label;btn.setAttribute('aria-label',label+':'+config.notespaneltitle);Utils.sessionSet(key,collapsed?'1':'0',labelContext)}setCollapsed(Utils.sessionGet(key,labelContext)==='1');btn.addEventListener('click',function(){var isCollapsed=btn.getAttribute('aria-expanded')==='false';setCollapsed(!isCollapsed)})}return{appendRow:appendRow,getRemainingChars:getRemainingChars,updateCharCounter:updateCharCounter,setButtonState:setButtonState,installHandler:installHandler,installToggle:installToggle}});
